		w.Write([]byte(`{"status":"ok"}`))
	})

	goawayHandler := filters.WithProbabilisticGoaway(backendHandler, 0.02)

	service := &testService{
		name:    "test-service",
		client:  kubeClient,
		handler: goawayHandler,
	}

	go func() {
		service.Run(ctx)
	}()

	if err := service.WaitForReady(ctx); err != nil {
		t.Fatalf("Service failed to start: %v", err)
	}

	port := service.Port()
	apiService := &apiregistrationv1.APIService{
		ObjectMeta: metav1.ObjectMeta{Name: "v1.test.example.com"},
		Spec: apiregistrationv1.APIServiceSpec{
			Group:                 "test.example.com",
			Version:               "v1",
			InsecureSkipTLSVerify: true,
			GroupPriorityMinimum:  1000,
			VersionPriority:       15,
			Service: &apiregistrationv1.ServiceReference{
				Namespace: "default",
				Name:      service.Name(),
				Port:      port,
			},
		},
	}

	_, err = aggregatorClient.ApiregistrationV1().APIServices().Create(ctx, apiService, metav1.CreateOptions{})
	if err != nil {
		t.Fatalf("Failed to create APIService: %v", err)
	}

	time.Sleep(2 * time.Second)

	httpClient, err := rest.HTTPClientFor(server.ClientConfig)
	if err != nil {
		t.Fatal(err)
	}

	var successCount, goawayErrors int32
	totalRequests := 500
	concurrency := 25

	sem := make(chan struct{}, concurrency)
	done := make(chan struct{})

	for i := 1; i <= totalRequests; i++ {
		sem <- struct{}{}

		go func(reqNum int) {
			defer func() { <-sem }()

			requestBody := []byte(fmt.Sprintf(`{"request":%d}`, reqNum))
			req, err := http.NewRequest(
				"POST",
				server.ClientConfig.Host+"/apis/test.example.com/v1/resources",
				bytes.NewReader(requestBody),
			)
			if err != nil {
				return
			}
			req.Header.Set("Content-Type", "application/json")

			resp, err := httpClient.Do(req)
			if err != nil {
				if isGOAWAYError(err.Error()) {
					atomic.AddInt32(&goawayErrors, 1)
				}
				return
			}

			bodyBytes, _ := io.ReadAll(resp.Body)
			resp.Body.Close()

			if resp.StatusCode == http.StatusOK {
				atomic.AddInt32(&successCount, 1)
			} else if isGOAWAYError(string(bodyBytes)) {
				atomic.AddInt32(&goawayErrors, 1)
			}
		}(i)
	}

	for i := 0; i < cap(sem); i++ {
		sem <- struct{}{}
	}
	close(done)

	if atomic.LoadInt32(&goawayErrors) == 0 {
		t.Skip("No GOAWAY errors observed in this test run")
	}

	t.Errorf("GOAWAY retry failures detected: %d", atomic.LoadInt32(&goawayErrors))
}

type testService struct {
	name    string
	client  kubernetes.Interface
	handler http.Handler
	server  *httptest.Server
	port    *int32
}

func (s *testService) Run(ctx context.Context) error {
	s.server = httptest.NewUnstartedServer(s.handler)

	http2Options := &http2.Server{}
	if err := http2.ConfigureServer(s.server.Config, http2Options); err != nil {
		return err
	}

	s.server.TLS = s.server.Config.TLSConfig
	s.server.StartTLS()

	serverURL, _ := url.Parse(s.server.URL)
	serverPort, _ := strconv.Atoi(serverURL.Port())
	port := int32(serverPort)

	_, err := s.client.CoreV1().Services("default").Apply(
		ctx,
		corev1apply.Service(s.name, "default").
			WithSpec(corev1apply.ServiceSpec().
				WithPorts(corev1apply.ServicePort().WithPort(port)).
				WithType("ExternalName").
				WithExternalName("localhost")),
		metav1.ApplyOptions{FieldManager: "test-manager"},
	)
	if err != nil {
		return err
	}

	s.port = &port

	<-ctx.Done()
	s.server.Close()
	s.client.CoreV1().Services("default").Delete(ctx, s.name, metav1.DeleteOptions{})
	return nil
}

func (s *testService) WaitForReady(ctx context.Context) error {
	return wait.PollUntilContextTimeout(ctx, 200*time.Millisecond, 5*time.Second, false,
		func(ctx context.Context) (done bool, err error) {
			return s.Port() != nil, nil
		})
}

func (s *testService) Port() *int32 {
	return s.port
}

func (s *testService) Name() string {
	return s.name
}

func isGOAWAYError(msg string) bool {
	return strings.Contains(msg, "Transport: cannot retry")
}
